import { Injectable } from '@angular/core';
import {Observable} from 'rxjs/Observable';
import { Http } from '@angular/http';
import 'rxjs/add/operator/map';

declare var require: any;


export class User {
  uid: number;
  fullname: string;
  username: string;
  email: string;
  password: string;
  typeofuser: string;
  mailsubscription: string;

  constructor(uid: number, fullname: string, username: string, 
    email: string, password:string, typeofuser: string, mailsubscription: string) {
    this.uid = uid;
    this.fullname = fullname;
    this.username = username;
    this.email = email;
    this.password = password;
    this.typeofuser = typeofuser;
    this.mailsubscription = mailsubscription;

  }

}

@Injectable()
export class AuthService {
  currentUser: User;
  debug: boolean = false;
  hardware:boolean = false;

  constructor(private http: Http) {

  }

  public createUser(uid, fullname, username, email, password, typeofuser, mailsubscription){
    this.currentUser = new User(uid, fullname, username, email, password, typeofuser, mailsubscription);
  }

  private clearURL(string){
    string = string.split('%').join('%25');
    string = string.split('/').join('%2F');
    string = string.split('+').join('%2B');
    return string;
  }

  public clearJSON(data){
    for(var d in data){
      if(typeof data[d] === "string") {
        data[d] = this.clearURL(data[d]);

      }else if(Array.isArray(data[d])){
        for(var i=0;i<data[d].length;i++) {
          data[d][i] = this.clearJSON(data[d][i]);
        }
      }
    }
    return data;
  }

  private encryptToString(data){
    var CryptoJS = require('crypto-js');
    var encrypted;
    encrypted = CryptoJS.AES.encrypt(JSON.stringify(data),'h2ocrop2017ICOM5047').toString();
    return encrypted;
  }

  private encryptToURL(data) {
    var encrypted;
    encrypted = this.encryptToString(data);
    encrypted = this.clearURL(encrypted);
    return encrypted;
  }

  private accessDatabaseURL(url) {
    return this.http.get(url).map(res => res.json());
  }

  private accessDatabase(url, data) {
    var encrypted = this.encryptToURL(data);
    url = url+encrypted;
    return this.accessDatabaseURL(url);
  }

